INSERT INTO "KodVred_2" ("ID","SpisokCode","Code","RazdelCode","Name") VALUES (883,1,'1080А02А-17531','VIII','В производстве асбестовых технических изделий в нижеследующих цехах, участках и отделениях: подготовительном (приготовительном), текстильном, прядильном, ткацком, аппаратном, набивочном, автотракторных деталей, автоформованных деталей, спиральнонавитых прокладок, картона и фильтров, паранитовом, вальцленты (эластичного материала), опытно-эксперементальном, промтехники. Рабочие, занятые на ремонте, профилактике и обслуживании технологического и электрооборудования (кроме контрольно- измерительных приборов и вентиляции)');
