INSERT INTO "PlatCategory" ("ID","Code","Name","FullName","DateBegin","DateEnd","PlatCategoryRaschPerID") VALUES (139,'АСБ','АПТЕЧНЫЕ ОРГАНИЗАЦИИ, ОРГАНИЗАЦИИ СОЦИАЛЬНОГО ОБСЛУЖИВАНИЯ НАСЕЛЕНИЯ И БЛАГОТВОРИТЕЛЬНЫЕ ОРГАНИЗАЦИИ','Указывается для работников плательщиков страховых взносов, которые применяют пониженный тариф |страховых взносов в соответствии с пунктами 10-12 части 1 и пунктом 3.4. части 2 статьи 58 |Федерального закона от 24.07.2009 № 212-ФЗ','2012-01-01',NULL,4);
INSERT INTO "PlatCategory" ("ID","Code","Name","FullName","DateBegin","DateEnd","PlatCategoryRaschPerID") VALUES (140,'БЕЗР','БЕЗРАБОТНЫЙ','Лицо, получающее пособие по безработице','2010-01-01',NULL,4);
INSERT INTO "PlatCategory" ("ID","Code","Name","FullName","DateBegin","DateEnd","PlatCategoryRaschPerID") VALUES (141,'ВЖНР','ВРЕМЕННО ПРОЖИВАЮЩИЙ/НАЕМ/РАБОТНИК','Указывается страхователями, у которых отсутствует право применения пониженных тарифов страховых |взносов  в отношении застрахованных лиц из числа иностранных граждан или лиц без гражданства |(за исключением высококвалифицированных специалистов в соответствии с Федеральным законом от |25 июля 2002 года № 115-ФЗ "О правовом положении иностранных граждан в Российской Федерации"), |временно проживающих на территории Российской Федерации и заключивших трудовой договор на |неопределенный срок либо сро','2012-01-01',NULL,4);
INSERT INTO "PlatCategory" ("ID","Code","Name","FullName","DateBegin","DateEnd","PlatCategoryRaschPerID") VALUES (142,'ВЖСБ','АПТЕЧНЫЕ ОРГАНИЗАЦИИ, ОРГАНИЗАЦИИ СОЦИАЛЬНОГО ОБСЛУЖИВАНИЯ НАСЕЛЕНИЯ И БЛАГОТВОРИТЕЛЬНЫЕ ОРГАНИЗАЦИИ','Указывается для работников из числа иностранных граждан или лиц без гражданства (за исключением |высококвалифицированных специалистов в соответствии с Федеральным законом от 25 июля 2002 года |№ 115-ФЗ "О правовом положении иностранных граждан в Российской Федерации"), временно проживающих |на территории Российской Федерации и заключивших трудовой договор на неопределенный срок либо |срочный трудовой договор на срок не менее шести месяцев (статья 22.1 Федерального закона от |15.12.2001 № 167-ФЗ','2012-01-01',NULL,4);
INSERT INTO "PlatCategory" ("ID","Code","Name","FullName","DateBegin","DateEnd","PlatCategoryRaschPerID") VALUES (143,'ВЖСХ','ВРЕМЕННО ПРОЖИВАЮЩИЙ /С/Х ТОВАРО-ПРОИЗВОДИТЕЛИ','Указывается плательщиками страховых взносов, отвечающих критериям, указанным в статье 346 Налогового |кодекса Российской Федерации (указывается для плательщиков страховых взносов, которые применяют |пониженный тариф страховых взносов в соответствии с пунктом 1 части 2 статьи 57 и пунктом 1 части |1 статьи 58 Федерального закона от 24.07.2009 № 212-ФЗ "О страховых взносах в Пенсионный фонд |Российской Федерации, Федеральный фонд социального страхования Российской Федерации, Фонд |обязательного ме','2012-01-01','2014-12-31',4);
