INSERT INTO "PlatCategory" ("ID","Code","Name","FullName","DateBegin","DateEnd","PlatCategoryRaschPerID") VALUES (187,'ВЖКС','ВРЕМЕННО ПРОЖИВАЮЩИЙ НАЕМ/РАБОТНИК','Указывается для иностранных граждан и лиц без гражданства, временно проживающих на территории Российской Федерации, а также для временно пребывающих на территории Российской Федерации иностранных граждан или лиц без гражданства, которым предоставлено временное убежище в соответствии с Федеральным законом от 19.02.1993 № 4528-1 «О беженцах», с выплат в пользу которых плательщиками страховых взносов уплачиваются страховые взносы в соответствии со статьей 58.4 Федерального закона от 24.07.2009 № 212-ФЗ','2015-01-01',NULL,4);
