INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (2,'п1ч1с77тк','пункт 1 части 1 статьи 77 ТК РФ','Трудовой договор прекращен по соглашению сторон, пункт 1 части первой статьи 77 Трудового кодекса Российской Федерации.');
INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (3,'п2ч1с77тк','пункт 2 части 1 статьи 77 ТК РФ','Трудовой договор прекращен в связи с истечением срока трудового договора, пункт 2 части первой статьи 77 Трудового кодекса Российской Федерации.');
INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (4,'п3ч1с77тк','пункт 3 части 1 статьи 77 ТК РФ','Трудовой договор расторгнут по инициативе работника, пункт 3 части первой статьи 77 Трудового кодекса Российской Федерации.');
INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (5,'п5ч1с77тк','пункт 5 части 1 статьи 77 ТК РФ','Трудовой договор прекращен в связи с переводом работника по его просьбе или с его согласия на выборную работу (должность) пункт 5 части первой статьи 77 Трудового кодекса Российской Федерации.');
INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (6,'п6ч1с77тк','пункт 6 части 1 статьи 77 ТК РФ','Трудовой договор прекращен ввиду отказа работника от продолжения работы в связи со сменой собственника имущества организации, с изменением подведомственности (подчиненности) организации либо ее реорганизацией, с изменением типа государственного или муниципального учреждения, пункт 6 части первой статьи 77 Трудового кодекса Российской Федерации.');
INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (7,'п7ч1с77тк','пункт 7 части 1 статьи 77 ТК РФ','Трудовой договор прекращен ввиду отказа работника от продолжения работы в связи с изменением определенных сторонами условий трудового договора, пункт 7 части первой статьи 77 Трудового кодекса Российской Федерации.');
INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (8,'п8ч1с77тк','пункт 8 части 1 статьи 77 ТК РФ','Трудовой договор прекращен в связи с отказом работника от перевода на другую работу, необходимую ему в соответствии с медицинским заключением, выданным в порядке, установленном федеральными законами и иными нормативными правовыми актами Российской Федерации, либо отсутствие у работодателя соответствующей работы, пункт 8 части первой статьи 77 Трудового кодекса Российской Федерации.');
INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (9,'п9ч1с77тк','пункт 9 части 1 статьи 77 ТК РФ','Трудовой договор прекращен в связи с отказом работника от перевода на работу в другую местность вместе с работодателем, пункт 9 части первой статьи 77 Трудового кодекса Российской Федерации.');
INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (10,'п11ч1с77тк','пункт 11 части 1 статьи 77 ТК РФ','Трудовой договор прекращен в связи с нарушением установленных Трудовым кодексом правил заключения трудового договора, пункт 11 части первой статьи 77 Трудового кодекса Российской Федерации.');
