INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (116,'п12ч2с83фз141','Пункт 12 части 2 статьи 83','В связи с истечением срока нахождения сотрудника в распоряжении федерального органа исполнительной власти в области пожарной безопасности или подразделения.');
