INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (150,'п5ч5с8фз6','Пункт 5 части 5 статьи 8','Нарушение требований законодательства Российской Федерации при осуществлении возложенных на него должностных полномочий или злоупотребления должностными полномочиями, если за решение о досрочном освобождении такого должностного лица проголосует большинство от установленного числа депутатов законодательного (представительного) органа.');
