INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (158,'п3ч1с27фз25','Пункт 3 части 1 статьи 27 ','За совершение дисциплинарного проступка - неисполнение или ненадлежащее исполнение муниципальным служащим по его вине возложенных на него служебных обязанностей - представитель нанимателя (работодатель) имеет право применить следующие дисциплинарные взыскания, предусматривается увольнение с муниципальной службы по соответствующим основаниям.');
