INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (162,'п4ч2с30фз403','Пункт 4 части 2 статьи 30','Несоблюдение ограничений, нарушения запретов и неисполнения обязанностей, связанных с прохождением службы в Следственном комитете и установленных статьей 17 настоящего Федерального закона, а также возникновения обстоятельств, предусмотренных статьей 16 Федерального закона «О государственной гражданской службе Российской Федерации».');
