INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (166,'п8ч2с30фз403','Пункт 8 части 2 статьи 30','Отсутствие на службе более четырех месяцев в общей сложности в течение двенадцати месяцев в связи с временной нетрудоспособностью, если законодательством Российской Федерации не установлен более длительный срок сохранения места работы (должности) при определенном заболевании или если для определенной категории граждан законодательством Российской Федерации не предусмотрены гарантии по сохранению места работы (должности). ');
