INSERT INTO "DictionaryReasonFired" ("ID","Code","CodeFull","Name") VALUES (281,'п12ч3с80фз328','Пункт 12 части 3 статьи 80','В связи с истечением срока, установленного частью 5 статьи 35 настоящего Федерального закона для возобновления службы в органах принудительного исполнения;13) в связи с отказом сотрудника без уважительных причин от перевода на равнозначную должность в порядке ротации в соответствии с частью 11 статьи 30 настоящего Федерального закона.');
