INSERT INTO "TerrUsl" ("ID","Code","Name","DateBegin","DateEnd","AKT") VALUES (7,'МКС','Местность, приравненная к районам Крайнего Севера, на 31 декабря 2001 года','1996-01-01',NULL,'Пункты 2, 6 и 7 части 1 и часть 2 статьи 32 Федерального закона от 28 декабря 2013 г. № 400-ФЗ «О страховых пенсиях». Перечень районов Крайнего Севера и приравненных к ним местностей, утвержденный постановлением Совета Министров СССР от 10 ноября 1967 г.  № 1029 и действующий в редакции постановления Совета Министров СССР от 3 января 1983 г. № 12 с последующими изменениями и дополнениями по состоянию на 31 декабря 2001 года');
