INSERT INTO "TerrUsl" ("ID","Code","Name","DateBegin","DateEnd","AKT") VALUES (18,'МКС-РКСР','Местность, приравненная к районам Крайнего Севера, на 31 декабря 2001 года и район Крайнего Севера в отчетном периоде',NULL,NULL,'Пункты 2, 6 и 7 части 1 и часть 2 статьи 32 Федерального закона от 28 декабря 2013 г. № 400-ФЗ «О страховых пенсиях». Перечень районов Крайнего Севера и приравненных к ним местностей, утвержденный постановлением Совета Министров СССР от 10 ноября 1967 г.  № 1029 и действующий в редакции постановления Совета Министров СССР от 3 января 1983 г. № 12 с последующими изменениями и дополнениями по состоянию на 31 декабря 2001 года. Части 4 и 7 статьи 17 Федерального закона от 28 декабря 2013 г. № 400-ФЗ «О страховых пенсиях». Перечень районов Крайнего Севера и местностей, приравненных к районам Крайнего Севера, в целях предоставления государственных гарантий и компенсаций для лиц, работающих и проживающих в этих районах и местностях, утвержденный постановлением Правительства Российской Федерации от 16 ноября 2021 г. № 1946, действующий в отчетном периоде');
